"""本地视频 Provider：用于开发、联调和自动化测试。"""

from base64 import b64decode
from typing import ClassVar
from uuid import uuid4

from app.core.errors import GenerationFailedError
from app.providers.video import VideoGenerationHandle, VideoGenerationStatus


_FIXTURE_MP4 = b64decode(
    ""
)


class FakeVideoProvider:
    _submitted: ClassVar[set[str]] = set()

    def __init__(self, **_options: object) -> None:
        pass

    async def submit_video(self, **_kwargs: object) -> VideoGenerationHandle:
        handle = VideoGenerationHandle(uuid4().hex)
        self._submitted.add(handle.id)
        return handle

    async def poll_video(self, handle: VideoGenerationHandle) -> VideoGenerationStatus:
        if handle.id not in self._submitted:
            raise GenerationFailedError("Fake 视频任务不存在")
        return VideoGenerationStatus("succeeded", 100)

    async def download_video(self, handle: VideoGenerationHandle) -> bytes:
        if handle.id not in self._submitted:
            raise GenerationFailedError("Fake 视频任务不存在")
        # 可被 ffprobe 解码的 16x16 H.264 短视频，覆盖完整媒体校验链路。
        return _FIXTURE_MP4
